-- Book Meet: поводы познакомиться, пол профиля и справочник городов СНГ.
-- Справочник: GeoNames cities500, CC BY 4.0, https://www.geonames.org/

CREATE TABLE IF NOT EXISTS cities (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  geoname_id BIGINT UNSIGNED NULL,
  name VARCHAR(180) NOT NULL,
  name_key VARCHAR(180) NOT NULL,
  country_code CHAR(2) NOT NULL,
  country_name VARCHAR(120) NOT NULL,
  population BIGINT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  UNIQUE KEY cities_geoname_unique (geoname_id),
  KEY cities_name_key_idx (name_key),
  KEY cities_country_name_idx (country_code, name_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS occasions (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  creator_user_id BIGINT UNSIGNED NOT NULL,
  occasion_type VARCHAR(30) NOT NULL,
  primary_text TEXT NOT NULL,
  audience_text TEXT NOT NULL,
  target_gender VARCHAR(20) NOT NULL DEFAULT 'Все',
  target_cities LONGTEXT NOT NULL,
  target_profile_type VARCHAR(20) NOT NULL DEFAULT 'Все',
  status VARCHAR(30) NOT NULL DEFAULT 'pending',
  moderation_note TEXT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY occasions_creator_status_idx (creator_user_id, status),
  KEY occasions_status_created_idx (status, created_at),
  CONSTRAINT occasions_creator_fk FOREIGN KEY (creator_user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

